    public List<KPI> getAllKPI() 
    throws ProcessingException {
        List<KPI> list = null;

        try {
        	CompletableFuture<List<KPI>> futureList = queryGateway.query(new FindAllKPIQuery(), ResponseTypes.multipleInstancesOf(KPI.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all KPI";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Campaign on KPI
     * @param		command AssignCampaignToKPICommand	
     * @exception	ProcessingException
     */     
	public void assignCampaign( AssignCampaignToKPICommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getKPIId() );
		
		CampaignService childDelegate 	= CampaignService.getCampaignInstance();
		KPIService parentDelegate = KPIService.getKPIInstance();			
		UUID childId = command.getAssignment().getCampaignId();
		Campaign child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Campaign using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

